INSERT INTO feature VALUES('rap-jobs','editor','Long toolset operations as jobs','rap-toolset','implemented','uncommon','mainstream editors','`check`, `test`, `replay` and `run` are long operations of the toolset. The manifest offers them, and `tools/list` does not. Each call is acknowledged at once and runs as a job. `check` and `test` walk their paths on the hub''s pool as the command line walks them, and the result is the verdict line that `gandr check` or `gandr test` prints, with every line it prints as the `display_as`. `replay` answers once the admission of the revision that the hub holds ends, with the declarations counted by the kernel''s warrant. `run` answers the line of a declaration''s run, as its run lens shows it. A run of the toolset and of the run lens takes the lock of the workspace only to read what it reads, and runs on the hub''s pool with no lock, so each editor goes on during a long run. A newer revision of a document that a `check`, a `test`, a `replay` or a `run` reads retires it, and the retired call names the document and its version. `/cancel_tool_call` and `/close_thread` end a job, which answers `cancelled`. The hub''s build with the `instrument` feature sends each running job the activity card of each tick as a `view_update`.','surface-agentic surface-driver surface-lsp','crates/surface-agentic/src/rap.rs crates/surface-driver/tests/cli.rs crates/surface-lsp/src/server.rs',NULL,'#6342');
